import{_ as t,o as e,c as l,ag as o}from"./chunks/framework.CvZZEx4j.js";const h=JSON.parse('{"title":"背景音乐 (BGM)","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/bgm.md","filePath":"advanced/bgm.md","lastUpdated":null}'),r={name:"advanced/bgm.md"};function i(n,a,s,d,c,m){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="背景音乐-bgm" tabindex="-1">背景音乐 (BGM) <a class="header-anchor" href="#背景音乐-bgm" aria-label="Permalink to &quot;背景音乐 (BGM)&quot;">​</a></h1><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>AI 在输出中使用 <code>&lt;bgm&gt;</code> 标签指定音乐名称，插件会自动在线搜索并播放匹配的音乐。</p><p>例如，AI 输出 <code>&lt;bgm&gt;夜晚的雨声&lt;/bgm&gt;</code>，插件会搜索相关音乐并播放。</p><h2 id="bgm-白名单" tabindex="-1">BGM 白名单 <a class="header-anchor" href="#bgm-白名单" aria-label="Permalink to &quot;BGM 白名单&quot;">​</a></h2><p>你可以在 <strong>设置面板</strong> 中配置 BGM 白名单——限制 AI 只能从指定的歌单中选择音乐：</p><ol><li>打开设置面板</li><li>找到「BGM 白名单」</li><li>添加允许的歌曲名称</li><li>注入世界书后，AI 将只从白名单中选择 BGM</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>如果不设置白名单，AI 会根据剧情自由选择真实存在的音乐名称。</p></div><h2 id="播放控制" tabindex="-1">播放控制 <a class="header-anchor" href="#播放控制" aria-label="Permalink to &quot;播放控制&quot;">​</a></h2><ul><li><strong>播放/暂停</strong>：点击工具栏的 BGM 按钮</li><li><strong>音量调节</strong>：在设置面板中拖动音量滑块</li><li><strong>暂停记忆</strong>：如果你主动暂停 BGM，在你手动恢复之前不会自动播放新 BGM</li></ul>',10)])])}const p=t(r,[["render",i]]);export{h as __pageData,p as default};
